import os


def read_records(path, size):
    with open(path, "rb") as f:
        data = f.read()
    return [bytearray(data[i:i + size]) for i in range(0, len(data), size)]


def write_records(path, recs):
    with open(path, "wb") as f:
        for r in recs:
            f.write(bytes(r))


def num(field):
    # PIC 9 field: spaces read as zero
    v = 0
    for c in field:
        v = v * 10 + (c - 48 if 48 <= c <= 57 else (c & 0x0F if c != 32 else 0))
    return v


def main():
    with open("src/INPUT.DAT", "rb") as f:
        raw = f.read(22)
    if not raw:
        print("Error: Input file is empty")
        return
    raw = raw.ljust(22, b" ")
    buyer, seller, book = raw[0:4], raw[4:8], raw[8:12]
    amount = num(raw[12:22])

    acc = read_records("data/ACCOUNTS.DAT", 34)
    books = read_records("data/BOOKS.DAT", 28)

    bf = sf = kf = vo = False
    for r in acc:
        if bytes(r[0:4]) == buyer:
            bf = True
        if bytes(r[0:4]) == seller:
            sf = True
    for r in books:
        if bytes(r[0:4]) == book:
            kf = True
            if bytes(r[24:28]) == seller:
                vo = True
    print(" ")

    if not (bf and sf and kf and vo):
        print("Transaction failed due to validation errors")
        return

    M = 10 ** 10
    for r in acc:
        if bytes(r[0:4]) == buyer:
            bal = abs(num(r[24:34]) - amount) % M
            r[24:34] = b"%010d" % bal
        if bytes(r[0:4]) == seller:
            bal = (num(r[24:34]) + amount) % M
            r[24:34] = b"%010d" % bal
    write_records("data/ACCOUNTS.DAT", acc)

    for r in books:
        if bytes(r[0:4]) == book:
            r[24:28] = buyer
    write_records("data/BOOKS.DAT", books)

    with open("data/TRANSACTIONS.DAT", "ab") as f:
        f.write(book + b"%010d" % amount + seller + buyer)
    print("Transaction completed successfully")


main()
